function decode(b64){ try { return Buffer.from(String(b64||"").replace(/-/g,"+").replace(/_/g,"/"),"base64").toString("utf8"); } catch(e){ return ""; } }
function getHeader(pl,name){ const h=(pl&&pl.headers)||[]; const f=h.find(x=>x.name&&x.name.toLowerCase()===name.toLowerCase()); return f?f.value:""; }
function bodyFromPayload(pl){
  if(!pl) return "";
  if(pl.body&&pl.body.data) return decode(pl.body.data);
  if(pl.parts&&pl.parts.length){
    const plain=pl.parts.find(p=>p.mimeType==="text/plain");
    if(plain&&plain.body&&plain.body.data) return decode(plain.body.data);
    const html=pl.parts.find(p=>p.mimeType==="text/html");
    if(html&&html.body&&html.body.data) return decode(html.body.data);
    for(const p of pl.parts){ const r=bodyFromPayload(p); if(r) return r; }
  }
  return "";
}
const strip = s => String(s||"")
  .replace(/<style[\s\S]*?<\/style>/gi," ").replace(/<script[\s\S]*?<\/script>/gi," ")
  .replace(/<[^>]+>/g," ").replace(/&nbsp;/gi," ").replace(/&amp;/gi,"&")
  .replace(/\s+/g," ").trim();

// Obvious noise that must never be read as "I applied here".
const NOISE = /(job alert|jobalert|new jobs|jobs for you|jobs matching|recommended for you|job recommendations|newsletter|job digest|saved search|jobbenachrichtigung|stellenangebote fuer dich|apply now|hiring now)/i;

const emails = [];
let skipped = 0;
for (const it of $input.all()) {
  const m = it.json;
  // Gmail step failed (e.g. expired login): it passes an error item instead of emails.
  // Skip application tracking for today; the job search still runs.
  if (m.error) { console.log("GMAIL FAILED, skipping application tracking today:", typeof m.error === "string" ? m.error : JSON.stringify(m.error).slice(0, 300)); continue; }
  const subject = m.subject || m.Subject || getHeader(m.payload, "Subject") || "";
  const from    = m.from    || m.From    || getHeader(m.payload, "From") || "";
  let body = m.text || "";
  if (!body) body = strip(m.html || "");
  if (!body) body = strip(bodyFromPayload(m.payload));
  if (!body) body = m.snippet || "";
  const date    = m.date || getHeader(m.payload, "Date") || (m.internalDate ? new Date(Number(m.internalDate)).toISOString() : "");
  // Gmail returns one empty item when nothing matched (alwaysOutputData) — skip it.
  if (!subject && !body) continue;
  if (NOISE.test(subject) || NOISE.test(String(body).slice(0, 400))) { skipped++; continue; }
  emails.push({ d: String(date).slice(0, 25), s: subject, f: from, b: String(body).slice(0, 900) });
}

const lines = [
  "These are emails from ONE person’s inbox.",
  "",
  "Extract ONLY emails that PROVE this person already SUBMITTED an application:",
  "  - an application confirmation / acknowledgement from an employer or its ATS, or",
  "  - a rejection or interview invitation that refers to an application they submitted.",
  "",
  "NEVER extract: job alerts, job recommendations, job-board digests, newsletters,",
  "recruiter cold outreach, marketing, or any email that merely mentions open roles.",
  "A company simply appearing in an email is NOT evidence of an application.",
  "If you are not certain the person actually applied, LEAVE IT OUT — omitting is always safer.",
  "",
  "For every genuine application return the employer name and the EXACT role title as written",
  "in the email. If no role title is stated anywhere, return an empty title.",
  "confidence = how sure you are that this person applied (0.0 - 1.0).",
  "date = the email's date (field d) as YYYY-MM-DD.",
  "",
  "Return ONLY a JSON array, no prose:",
  "[{\"company\":\"...\",\"title\":\"...\",\"kind\":\"applied|rejected|interview\",\"evidence\":\"max 12 words quoted from the email\",\"confidence\":0.0,\"date\":\"YYYY-MM-DD\"}]",
  "",
  "If EMAILS is empty, return [].",
  "",
  "EMAILS:",
  JSON.stringify(emails)
];

console.log("application-candidate emails:", emails.length, "| noise skipped:", skipped);
return [{ json: { prompt: lines.join("\n") } }];

// Keep only high-confidence, fully-identified applications.
// Anything vague is dropped here so it can never hide an un-applied job later.
const txt = $json.text || $json.response || "";
let arr = [];
try { const m = String(txt).match(/\[[\s\S]*\]/); arr = JSON.parse(m ? m[0] : txt); } catch (e) { arr = []; }
if (!Array.isArray(arr)) arr = [];

const MIN_CONFIDENCE = 0.7;
const ALLOWED_KINDS = ["applied", "rejected", "interview"];
const applied = [];
const rejectedRecords = [];

for (const x of arr) {
  if (!x || !x.company) { rejectedRecords.push("no company"); continue; }
  const company = String(x.company).trim();
  const title = String(x.title || "").trim();
  const kind = String(x.kind || "").toLowerCase().trim();
  const conf = typeof x.confidence === "number" ? x.confidence : 1;
  // No role title => we cannot tell WHICH job was applied to, so never filter on it.
  if (!title) { rejectedRecords.push(company + " (no title)"); continue; }
  if (conf < MIN_CONFIDENCE) { rejectedRecords.push(company + " (low confidence " + conf + ")"); continue; }
  if (kind && ALLOWED_KINDS.indexOf(kind) === -1) { rejectedRecords.push(company + " (kind " + kind + ")"); continue; }
  const date = /^\d{4}-\d{2}-\d{2}/.test(String(x.date || "")) ? String(x.date).slice(0, 10) : "";
  applied.push({ company, title, kind, date, evidence: String(x.evidence || "").slice(0, 120), confidence: conf });
}

console.log("applied records kept:", applied.length, "of", arr.length);
if (rejectedRecords.length) console.log("ignored records:", rejectedRecords.join(" | "));
for (const a of applied) console.log("APPLIED:", a.company, "//", a.title, "//", a.evidence);
return [{ json: { applied } }];

// Fetches the job boards that need NO credential: Greenhouse, Lever, Ashby (company career pages),
// Arbeitnow, RemoteOK, the German Federal Employment Agency (public API) and Jooble (key in "Your Settings").
// Each source is isolated: if one fails it is logged and skipped, the run continues.
const s = $('Your Settings').first().json;
const out = [];
const strip = (t) => String(t || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 4000);
const problems = [];
async function safe(label, fn) {
  const before = out.length;
  try { await fn(); if (out.length === before) problems.push(label + ': 0 jobs returned'); }
  catch (e) { const msg = String((e && (e.description || e.message)) || e).slice(0, 300); problems.push(label + ': ' + msg); console.log('source failed:', label, msg); }
}

for (const b of (s.greenhouseBoards || [])) await safe('greenhouse:' + b, async () => {
  const r = await this.helpers.httpRequest({ url: `https://boards-api.greenhouse.io/v1/boards/${b}/jobs?content=true`, json: true });
  for (const j of (r.jobs || [])) out.push({ source: 'greenhouse', source_id: String(j.id), title: j.title, company: b, location: (j.location && j.location.name) || '', url: j.absolute_url, description: strip(j.content), posted_at: j.updated_at || '', salary_min: null, salary_max: null });
});
for (const c of (s.leverCompanies || [])) await safe('lever:' + c, async () => {
  const r = await this.helpers.httpRequest({ url: `https://api.lever.co/v0/postings/${c}?mode=json`, json: true });
  for (const j of (r || [])) out.push({ source: 'lever', source_id: j.id, title: j.text, company: c, location: (j.categories && j.categories.location) || '', url: j.hostedUrl, description: strip(j.descriptionPlain || j.description), posted_at: j.createdAt ? new Date(j.createdAt).toISOString() : '', salary_min: null, salary_max: null });
});
for (const b of (s.ashbyBoards || [])) await safe('ashby:' + b, async () => {
  const r = await this.helpers.httpRequest({ url: `https://api.ashbyhq.com/posting-api/job-board/${b}?includeCompensation=true`, json: true });
  for (const j of (r.jobs || [])) out.push({ source: 'ashby', source_id: j.id, title: j.title, company: b, location: j.locationName || (j.location && j.location.name) || '', url: j.jobUrl || j.applyUrl, description: strip(j.descriptionPlain || j.description), posted_at: j.publishedDate || '', salary_min: null, salary_max: null });
});
if (s.useArbeitnow) await safe('arbeitnow', async () => {
  const r = await this.helpers.httpRequest({ url: 'https://www.arbeitnow.com/api/job-board-api', json: true });
  for (const j of (r.data || [])) out.push({ source: 'arbeitnow', source_id: j.slug, title: j.title, company: j.company_name, location: j.location || '', url: j.url, description: strip(j.description), posted_at: j.created_at ? new Date(j.created_at * 1000).toISOString() : '', salary_min: null, salary_max: null });
});
if (s.useRemoteOk) await safe('remoteok', async () => {
  const r = await this.helpers.httpRequest({ url: 'https://remoteok.com/api', json: true, headers: { 'User-Agent': 'n8n-job-scout' } });
  for (const j of (Array.isArray(r) ? r.slice(1) : [])) out.push({ source: 'remoteok', source_id: String(j.id), title: j.position, company: j.company, location: j.location || 'Remote', url: j.url, description: strip(j.description), posted_at: j.date || '', salary_min: j.salary_min || null, salary_max: j.salary_max || null });
});
// German Federal Employment Agency (Bundesagentur für Arbeit). 'jobboerse-jobsuche' is the agency's PUBLIC client id, not a personal key.
if (s.useArbeitsagentur) await safe('arbeitsagentur', async () => {
  const r = await this.helpers.httpRequest({
    url: `https://rest.arbeitsagentur.de/jobboerse/jobsuche-service/pc/v4/jobs?was=${encodeURIComponent(s.arbeitsagenturKeyword || '')}&wo=${encodeURIComponent(s.arbeitsagenturLocation || '')}&size=100`,
    headers: { 'X-API-Key': 'jobboerse-jobsuche' }, json: true });
  for (const j of (r.stellenangebote || [])) {
    const loc = j.arbeitsort ? [j.arbeitsort.ort, j.arbeitsort.region].filter(Boolean).join(', ') : '';
    out.push({ source: 'arbeitsagentur', source_id: j.refnr, title: j.titel || j.beruf || '', company: j.arbeitgeber || '', location: loc, url: j.externeUrl || ('https://www.arbeitsagentur.de/jobsuche/jobdetail/' + encodeURIComponent(j.refnr || '')), description: strip(j.beruf || ''), posted_at: j.aktuelleVeroeffentlichungsdatum || '', salary_min: null, salary_max: null });
  }
});
// Jooble puts the API key inside the URL path, which no n8n credential type supports,
// so its key lives in "Your Settings" (joobleApiKey). Skipped while the placeholder is still there.
const jk = String(s.joobleApiKey || '');
if (jk && !jk.startsWith('YOUR_')) for (const q of (s.joobleKeywords || [])) await safe('jooble:' + q, async () => {
  const r = await this.helpers.httpRequest({ method: 'POST', url: `https://jooble.org/api/${jk}`, body: { keywords: q, location: s.joobleLocation || '', page: '1' }, json: true });
  for (const j of (r.jobs || [])) out.push({ source: 'jooble:' + (j.source || ''), source_id: String(j.id || j.link), title: j.title, company: j.company || '', location: j.location || '', url: j.link, description: strip(j.snippet), posted_at: j.updated || '', salary_min: null, salary_max: null });
});

console.log('jobs from free boards:', out.length);
// Always return one item so the next steps run even if every free board failed.
return [{ json: { freeBoardJobs: out, problems } }];

// One item per JSearch query from "Your Settings", so the HTTP node below runs once per query.
const s = $('Your Settings').first().json;
return (s.jsearchQueries || []).map(q => ({ json: { query: q, country: s.jsearchCountry || 'de', datePosted: s.jsearchDatePosted || 'month' } }));

// One item per job-board URL from "Your Settings", so Firecrawl scrapes each board once.
const s = $('Your Settings').first().json;
return (s.firecrawlBoardUrls || []).map(url => ({ json: { boardUrl: url } }));

// Merges every source into ONE schema: source, source_id, title, company, location, url,
// description, posted_at, salary_min, salary_max. Missing/disabled/failed sources are skipped.
const strip = (t) => String(t || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 4000);
const from = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const out = [];
const problems = [];

for (const it of from('Fetch Free Job Boards')) { for (const j of (it.freeBoardJobs || [])) out.push(j); problems.push(...(it.problems || [])); }
// HTTP nodes continue on error and pass an "error" item instead of results: record it.
const httpError = (label, r) => { if (r && r.error) problems.push(label + ': ' + String(r.error.message || r.error.description || JSON.stringify(r.error)).slice(0, 300)); };
for (const r of from('Search Adzuna')) httpError('adzuna', r);
for (const r of from('Search JSearch')) httpError('jsearch', r);
for (const r of from('Scrape Boards with Firecrawl')) httpError('firecrawl', r);

for (const r of from('Search Adzuna')) for (const j of (r.results || [])) out.push({
  source: 'adzuna', source_id: String(j.id), title: j.title, company: (j.company && j.company.display_name) || '',
  location: (j.location && j.location.display_name) || '', url: j.redirect_url, description: strip(j.description),
  posted_at: j.created || '', salary_min: j.salary_min || null, salary_max: j.salary_max || null });

for (const r of from('Search JSearch')) for (const j of (Array.isArray(r.data) ? r.data : [])) out.push({
  source: 'jsearch:' + (j.job_publisher || 'google'), source_id: j.job_id, title: j.job_title, company: j.employer_name || '',
  location: [j.job_city, j.job_state, j.job_country].filter(Boolean).join(', '), url: j.job_apply_link || j.job_google_link,
  description: strip(j.job_description), posted_at: j.job_posted_at_datetime_utc || '', salary_min: j.job_min_salary || null, salary_max: j.job_max_salary || null });

const boards = from('List Firecrawl Boards');
from('Scrape Boards with Firecrawl').forEach((r, i) => {
  const jobs = (r.data && r.data.json && r.data.json.jobs) || [];
  const boardUrl = (r.data && r.data.metadata && r.data.metadata.sourceURL) || (boards[i] && boards[i].boardUrl) || '';
  const host = String(boardUrl).match(/^https?:\/\/(?:www\.)?([^\/?#:]+)/i); const name = host ? host[1] : 'board';
  for (const j of jobs) out.push({ source: 'firecrawl:' + name, source_id: j.url || (name + ':' + (j.title || '')), title: j.title || '',
    company: j.company || '', location: j.location || '', url: j.url || boardUrl, description: strip(j.description || ''),
    posted_at: j.postedDate || '', salary_min: null, salary_max: null });
});

const bySource = {};
for (const j of out) { const k = String(j.source).split(':')[0]; bySource[k] = (bySource[k] || 0) + 1; }
for (const k of ['adzuna', 'jsearch', 'firecrawl']) if (!bySource[k] && !problems.some(p => p.startsWith(k))) problems.push(k + ': 0 jobs returned (no credential, deactivated, or no results)');
console.log('fetched jobs:', out.length, JSON.stringify(bySource), '| problems:', JSON.stringify(problems));
// Run report on the FIRST job (open this node's output to see it): jobs per source + every source that failed or returned nothing.
const jobs = out.filter(j => j.title && j.url);
return jobs.map((j, i) => ({ json: i === 0 ? { ...j, _fetch_report: { fetched: out.length, bySource, problems } } : j }));

// Pure-logic hard filters (location, age, salary, dealbreakers). Relevance is NOT judged here —
// the AI checks each job description against the CV in "Check Jobs Against CV".
const cfg = $('Your Settings').first().json;
const now = Date.now();

// Simple stable string hash (no 'crypto' module — n8n blocks it).
// Combines two hashes for a longer, low-collision key.
function hashStr(s) {
  let h1 = 5381, h2 = 52711;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = ((h1 << 5) + h1 + c) >>> 0;   // djb2
    h2 = ((h2 << 5) + h2 ^ c) >>> 0;   // variant
  }
  return (h1 >>> 0).toString(16).padStart(8, '0') + (h2 >>> 0).toString(16).padStart(8, '0');
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const title = (j.title || '').toLowerCase();
  const loc = (j.location || '').toLowerCase();
  const text = title + ' ' + (j.description || '').toLowerCase();
  if (!j.title || !j.url) continue;
  if ((cfg.dealbreakerKeywords || []).some(d => text.includes(d.toLowerCase()))) continue;
  // There is no job-title gate on purpose: relevance is decided by the AI from the job DESCRIPTION vs your CV.
  // Remote counts only when the job's own location or title says so. "Hybrid" or "remote" somewhere in the
  // description is not enough: a hybrid job in Amsterdam is still in Amsterdam.
  const remoteHit = cfg.remoteOk && /\b(remote|anywhere|worldwide|home ?office|work from home|wfh)\b/.test(loc + ' ' + title);
  const locHit = (cfg.locations || []).some(l => loc.includes(l.toLowerCase()));
  if ((cfg.locations || []).length && !remoteHit && !locHit) continue;
  if (j.posted_at && cfg.maxAgeDays) { const t = Date.parse(j.posted_at); if (!isNaN(t) && (now - t) / 86400000 > cfg.maxAgeDays) continue; }
  if (cfg.salaryFloorEUR && j.salary_max && j.salary_max < cfg.salaryFloorEUR) continue;
  const hash = hashStr((title + '|' + (j.company || '') + '|' + (j.url || '')).toLowerCase());
  out.push({ json: { ...j, hash, status: 'new', fetched_at: new Date().toISOString() } });
}
console.log('survived hard filters:', out.length);
return out;

// Drop a job when the Data Table already has a row for the SAME company AND the EXACT same
// title (100% match), either because you applied to it or because it was already shortlisted
// on an earlier day (job boards like Jooble change their links daily, so "Skip Jobs Seen Before"
// alone can't recognise them). When in doubt, keep the job.
// Source of truth = every row in the Data Table (applied, shortlisted, or anything else)
// plus today's freshly parsed applications in case their insert hasn't landed.
const tableRows = $("Load Saved Jobs").all()
  .map(i => i.json)
  .filter(r => r && r.company && r.title);
const fresh = ($("Keep Confident Applications").first().json.applied) || [];
const known = tableRows.map(r => ({ company: r.company, title: r.title, status: r.status || "?" }))
  .concat(fresh.map(a => ({ company: a.company, title: a.title, status: "applied" })));

const cnorm = s => String(s || "").toLowerCase()
  .replace(/\b(gmbh|mbh|inc|ltd|limited|llc|co|corp|corporation|ag|se|bv|nv|oy|ab|sa|plc|kg|ug|e v|group|holding|holdings)\b/g, " ")
  .replace(/[^a-z0-9 ]/g, " ").replace(/\s+/g, " ").trim();

const tnorm = s => String(s || "").toLowerCase()
  .replace(/\(.*?\)/g, " ")
  .replace(/\b(m w d|w m d|d m w|m f d|f m x|all genders|gn|divers|full time|fulltime|part time|parttime|vollzeit|teilzeit|festanstellung|permanent|remote|hybrid|onsite)\b/g, " ")
  .replace(/[^a-z0-9 ]/g, " ").replace(/\s+/g, " ").trim();

// Two-letter words count (AI, ML, BI, QA, HR, UX, IT ...); only filler words are ignored.
const STOP = new Set(["the", "and", "for", "with", "our", "you", "your", "job", "jobs", "role", "position", "stelle", "als", "new",
  "in", "of", "to", "at", "on", "an", "or", "as", "by", "is", "we", "im", "zu", "am", "um", "de", "en", "la", "le", "et", "und", "der", "die", "das", "mit", "fur"]);
const toks = s => new Set(tnorm(s).split(" ").filter(w => w.length > 1 && !STOP.has(w)));

const titleSim = (a, b) => {
  const A = toks(a), B = toks(b);
  if (!A.size || !B.size) return 0;
  let inter = 0;
  for (const t of A) if (B.has(t)) inter++;
  const union = A.size + B.size - inter;
  return union ? inter / union : 0;
};

// Company names must be equal after normalisation, or one must fully contain
// the other AND have at least 2 tokens (so "Google" never matches "Google Cloud").
const companyMatch = (a, b) => {
  const A = cnorm(a), B = cnorm(b);
  if (!A || !B) return false;
  if (A === B) return true;
  const TA = new Set(A.split(" ").filter(Boolean));
  const TB = new Set(B.split(" ").filter(Boolean));
  const small = TA.size <= TB.size ? TA : TB;
  const large = TA.size <= TB.size ? TB : TA;
  if (small.size < 2) return false;
  for (const t of small) if (!large.has(t)) return false;
  return true;
};

// 1.0 = 100% title match: same words after removing gender tags (m/w/d), brackets,
// remote/hybrid/full-time etc. "Senior AI Engineer" does NOT match "AI Engineer".
const TITLE_THRESHOLD = 1.0;
const kept = [];
const dropped = [];

for (const it of $input.all()) {
  const j = it.json;
  let best = null;
  for (const ap of known) {
    if (!companyMatch(ap.company, j.company)) continue;
    const s = titleSim(ap.title, j.title);
    if (s >= TITLE_THRESHOLD && (!best || s > best.score)) best = { score: s, ap };
  }
  if (best) {
    dropped.push({ status: best.ap.status, text: (j.company || "?") + " / " + (j.title || "?") + "  <= " + best.ap.status + ": " + best.ap.company + " / " + best.ap.title + " (sim " + best.score.toFixed(2) + ")" });
  } else {
    kept.push(it);
  }
}

const byStatus = {};
for (const x of dropped) byStatus[x.status] = (byStatus[x.status] || 0) + 1;
console.log("known rows:", known.length, "| jobs in:", $input.all().length, "| kept:", kept.length, "| dropped:", dropped.length, JSON.stringify(byStatus));
for (const x of dropped) console.log("DROPPED as already known:", x.text);
// Summary on the first kept item so it shows in the execution log.
if (kept.length) kept[0] = { json: { ...kept[0].json, _known_report: { dropped: dropped.length, byStatus, examples: dropped.slice(0, 15).map(x => x.text) } }, pairedItem: kept[0].pairedItem };
return kept;

// Send each job's DESCRIPTION + the CV to the AI. The title is NOT used to judge fit.
const BATCH = 6;                       // jobs per AI call (descriptions are long)
const cfg = $('Your Settings').first().json;
const cv = String(cfg.cvText || '').trim();
if (!cv || cv.startsWith('PASTE YOUR CV')) throw new Error('cvText is empty: paste your CV as plain text into the "Your Settings" node.');
const homeCountry = String(cfg.homeCountry || 'your country');
const minYears = Number(cfg.dropIfYearsRequiredAtLeast) || 5;   // drop jobs that REQUIRE at least this many years
const dropSenior = cfg.dropSeniorRoles !== false;                 // drop explicitly mid-level / senior roles
const today = new Date().toISOString().slice(0, 10);

// --- 1. Merge duplicates: the same job often arrives via several links/boards. ---
// Same company + same title (ignoring m/w/d, brackets, remote etc.) = one job; keep the longest description.
const cnorm = s => String(s || '').toLowerCase()
  .replace(/\b(gmbh|mbh|inc|ltd|limited|llc|co|corp|corporation|ag|se|bv|nv|oy|ab|sa|plc|kg|ug|e v|group|holding|holdings)\b/g, ' ')
  .replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const tnorm = s => String(s || '').toLowerCase()
  .replace(/\(.*?\)/g, ' ')
  .replace(/\b(m w d|w m d|d m w|m f d|f m x|w m x|all genders|gn|divers|full time|fulltime|part time|parttime|vollzeit|teilzeit|festanstellung|permanent|remote|hybrid|onsite)\b/g, ' ')
  .replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const groups = new Map();
for (const j of $input.all().map(i => i.json)) {
  const key = cnorm(j.company) + '|' + tnorm(j.title);
  const prev = groups.get(key);
  if (!prev) groups.set(key, j);
  else if (String(j.description || '').length > String(prev.description || '').length) groups.set(key, j);
